mapper.select:
SELECT request_id, agreement_id, period_id, started_at, expired_at,
       target_contact_count, target_phone_count, target_email_count
FROM monthly_customer_contact_targets
WHERE agreement_id = #{agreementId}
ORDER BY period_id
LIMIT #{limit} OFFSET #{offset}

SELECT record_id, request_id, agreement_id, period_id, customer_profile_id,
       channel, confirmed_at
FROM customer_contact_records
WHERE request_id = #{requestId}
ORDER BY confirmed_at, record_id
LIMIT #{limit} OFFSET #{offset}
